<script setup>
import { computed } from 'vue';
import { recoveryGroups, recoverySchedule, recoveryTotals } from '../../lib/recovery-domain';
const props=defineProps({rows:{type:Array,required:true},section:{type:String,default:'schedule'}});
const schedule=computed(()=>recoverySchedule(props.rows));
const total=computed(()=>recoveryTotals(props.rows));
const groups=computed(()=>recoveryGroups(props.rows,props.section==='employees'));
const money=value=>'₹'+Number(value||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
const date=value=>value.toLocaleDateString('en-IN',{day:'numeric',month:'short'});
const labels={employees:'Booked by',branches:'Branch'};
const reconciliation=computed(()=>[['Gross pending due',total.value.gross],['Less: collected now',-total.value.collected],['Less: proposed for removal',-total.value.writeoff],['Real balance left',total.value.real],['Committed by client',total.value.committed],['Client dispute / on hold',total.value.dispute],['Not yet updated',total.value.pending]]);
</script>
<template>
<section v-if="section==='schedule'" class="pb-recovery-panel"><h2>Due-date Collection Calendar</h2><p>ERP scheduled dues and client commitments are independent views of the same invoices.</p><div class="pdr-due-cards"><article v-for="(card,index) in schedule" :key="card.name" class="pdr-due-card" :class="'due-'+index"><div class="pdr-due-top"><div><h3>{{card.name}}</h3><small>{{date(card.from)}}{{card.from.getTime()!==card.to.getTime()?' – '+date(card.to):''}}</small></div><span>{{['01','02','07','M'][index]}}</span></div><div class="pdr-due-scheduled"><span>ERP scheduled dues</span><strong>{{money(card.scheduled)}}</strong><small>{{card.invoices}} invoices · ERP next due date</small></div><div class="pdr-due-confirmed"><div><span>Confirmed collectable</span><small>{{card.commitments}} commitments · promised date</small></div><strong>{{money(card.confirmed)}}</strong></div></article></div></section>
<section v-else-if="section==='reconciliation'" class="pb-recovery-panel"><h2>Balance Reconciliation</h2><p>Commitments and disputes remain within the real balance left.</p><table><tbody><tr v-for="[label,value] in reconciliation" :key="label"><th>{{label}}</th><td>{{money(value)}}</td></tr></tbody></table></section>
<section v-else class="pb-recovery-panel"><h2>{{section==='employees'?'Booked-by Summary':'Branch Summary'}}</h2><div class="pb-table-scroll"><table><thead><tr><th>{{labels[section]}}</th><th>Invoices</th><th>Gross due</th><th>Collected</th><th>Committed</th><th>To remove</th><th>Real balance</th><th>Updated</th></tr></thead><tbody><tr v-for="group in groups" :key="group.key"><td>{{group.label}}<small v-if="group.branch">{{group.branch}}</small></td><td>{{group.n}}</td><td>{{money(group.gross)}}</td><td>{{money(group.collected)}}</td><td>{{money(group.committed)}}</td><td>{{money(group.writeoff)}}</td><td><strong>{{money(group.real)}}</strong></td><td>{{group.n?Math.round(group.done/group.n*100):0}}%</td></tr><tr v-if="!groups.length"><td colspan="8">Nothing to show.</td></tr></tbody><tfoot><tr><th>TOTAL</th><td>{{total.n}}</td><td>{{money(total.gross)}}</td><td>{{money(total.collected)}}</td><td>{{money(total.committed)}}</td><td>{{money(total.writeoff)}}</td><td>{{money(total.real)}}</td><td>{{total.n?Math.round(total.done/total.n*100):0}}%</td></tr></tfoot></table></div></section>
</template>
<style scoped>
.pb-recovery-panel{background:white;border:1px solid #e1e6ef;border-radius:14px;padding:20px;margin:18px 0;color:#29354b}.pb-recovery-panel h2{font-size:18px;margin:0 0 8px}.pb-recovery-panel p{font-size:13px;color:#64748b}.pdr-due-cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.pdr-due-card{background:#fff1e8;border:1px solid #e4d8cf;border-radius:16px;overflow:hidden;color:#9a5134}.due-1{background:#eaf2fc;color:#366e9f}.due-2{background:#f0ecfa;color:#76549c}.due-3{background:#fcf5de;color:#8f7130}.pdr-due-top{display:flex;justify-content:space-between;padding:16px}.pdr-due-top h3{font-size:15px;margin:0 0 5px}.pdr-due-top>span{font-size:25px;opacity:.6}.pdr-due-scheduled{display:grid;gap:8px;padding:0 16px 16px}.pdr-due-scheduled strong{font-size:24px}.pdr-due-confirmed{display:flex;align-items:center;justify-content:space-between;gap:8px;background:#ffffff88;padding:14px}.pdr-due-confirmed div{display:grid;gap:5px}small{display:block;font-size:11px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:12px;text-align:right;border-bottom:1px solid #e5e7eb;white-space:nowrap}th:first-child,td:first-child{text-align:left}tfoot{background:#f3f6fa;font-weight:700}.pb-table-scroll{overflow:auto}@media(max-width:1000px){.pdr-due-cards{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:540px){.pdr-due-cards{grid-template-columns:1fr}.pb-recovery-panel{padding:14px}}
</style>
